def compare_ops(a,b,o):
  results={}
  for op,fn in {'or':lambda x,y:x or y,'xor':lambda x,y:x!=y,'and':lambda x,y:x and y,'left':lambda x,y:x,'right':lambda x,y:y}.items():
    pred=[[fn(a[r][c]!=2,b[r][c]!=2) for c in range(13)] for r in range(len(a))]
    mismatches=sum(pred[r][c] != (o[r][c]==2) for r in range(len(o)) for c in range(13))
    results[op]=mismatches
  return results
